#!/usr/bin/env node
/**
 * Embeds the emergency page stylesheet (apps/portal/src/emergency/emergency.css — the single
 * source of truth) into the API's server-rendered emergency page as a minified string, so the
 * page needs no stylesheet request. Run after editing emergency.css:
 *   node scripts/sync-emergency-css.mjs
 * `--check` exits 1 when the generated file is out of date (run by an API unit test).
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

/** Conservative minifier: comments and redundant whitespace only (no rule rewriting). */
function minifyCss(css) {
  return css
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\s+/g, ' ')
    .replace(/\s*([{};,>])\s*/g, '$1')
    .replace(/;}/g, '}')
    .trim();
}

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const css = minifyCss(readFileSync(join(root, 'apps/portal/src/emergency/emergency.css'), 'utf8'));
const out = join(root, 'apps/api/src/modules/public-emergency/page/emergency-css.generated.ts');
const content =
  `// GENERATED by scripts/sync-emergency-css.mjs from apps/portal/src/emergency/emergency.css.\n` +
  `// Do not edit: change the source stylesheet and re-run the script.\n` +
  `export const EMERGENCY_PAGE_CSS = ${JSON.stringify(css)};\n`;
if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(out, 'utf8');
  } catch {
    /* missing */
  }
  if (current !== content) {
    console.error(
      'emergency-css.generated.ts is out of date: run node scripts/sync-emergency-css.mjs',
    );
    process.exit(1);
  }
} else {
  writeFileSync(out, content);
  console.log(`wrote ${out} (${css.length} bytes)`);
}
